{
  "title": "Discussion about working abroad, language and job search",
  "topics": [
    {
      "id": "working-abroad",
      "title": "Living and working abroad",
      "claims": [
        {
          "text": "Some participants know people living abroad: @AndriiRaccoon in Austria and walternet134 in Poland",
          "evidence": [3]
        },
        {
          "text": "P3 has at least two acquaintances in Austria, one recently arrived and another has been there for several years",
          "evidence": [12, 13]
        },
        {
          "text": "P3 has been living in Austria since 17.11.2025",
          "evidence": [49]
        },
        {
          "text": "P1 has been in Slovakia since around 03.09.2025",
          "evidence": [54]
        }
      ]
    },
    {
      "id": "language-requirements",
      "title": "Language requirements for jobs",
      "claims": [
        {
          "text": "German is the primary language spoken in Austria",
          "evidence": [14]
        },
        {
          "text": "Communication with Austrian contacts often happens in English",
          "evidence": [15]
        },
        {
          "text": "95% of vacancies require local language proficiency",
          "evidence": [26]
        },
        {
          "text": "Many candidates are filtered out because they lack language skills",
          "evidence": [27]
        },
        {
          "text": "Some hires occur even when candidates have limited local language knowledge",
          "evidence": [29]
        },
        {
          "text": "Typical language level requested is B2, B1 may suffice, certificates are rarely required",
          "evidence": [46]
        },
        {
          "text": "P3 is learning the local language because of daily life difficulties",
          "evidence": [47]
        }
      ]
    },
    {
      "id": "job-search-process",
      "title": "Job search experiences",
      "claims": [
        {
          "text": "Finding a job abroad was hard and took about 2 months",
          "evidence": [17]
        },
        {
          "text": "Advice to search for jobs on LinkedIn",
          "evidence": [18]
        },
        {
          "text": "Vacancy conversion rate is low: about 3 interviews out of ~100 applications",
          "evidence": [20, 21]
        },
        {
          "text": "Applications were sent regardless of language requirement mentions",
          "evidence": [36]
        },
        {
          "text": "Higher education rarely influences hiring decisions",
          "evidence": [32]
        }
      ]
    },
    {
      "id": "salary",
      "title": "Salary expectations",
      "claims": [
        {
          "text": "Salaries in Europe are generally higher than in Ukraine but still modest",
          "evidence": [35]
        },
        {
          "text": "P3 received a salary higher than a fast‑food minimum wage but still low",
          "evidence": [37]
        }
      ]
    },
    {
      "id": "personal-experience",
      "title": "Personal reflections and plans",
      "claims": [
        {
          "text": "P3 considers moving to Warsaw for an event",
          "evidence": [59]
        },
        {
          "text": "P3 lives with a boyfriend who has been in Austria >10 years, he is pessimistic about the country's future but personally prefers Austria over other European options",
          "evidence": [60]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Who lives in Bratislava or elsewhere in Slovakia, and who has moved abroad?",
      "evidence": [1]
    },
    {
      "text": "Do you personally feel like staying in Austria?",
      "evidence": [58]
    }
  ]
}
